s=[('it is raining','dy po ko'),('is raining now','po jo ko'),('is now it','po jo dy')]
ws=set(w for a,_ in s for w in a.split()); cs=set(c for _,b in s for c in b.split())
import itertools
sols=[]
for perm in itertools.permutations(sorted(cs)):
    m=dict(zip(sorted(ws),perm))
    if all(set(m[w] for w in a.split())==set(b.split()) for a,b in s): sols.append(m['raining'])
opts=['ko','dy','jo','po']
assert set(sols)=={'ko'}
assert sum(o in sols for o in opts)==1

# ring of 4 lateral faces around X, clockwise from top: view1 left,right = T,S ; view2 = M,R
# consistent ring must contain T followed by S and M followed by R
import itertools
lat=['T','S','M','R']; res=set()
for p in itertools.permutations(lat[1:]):
    ring=['T']+list(p)
    nxt={ring[i]:ring[(i+1)%4] for i in range(4)}
    if nxt['T']=='S' and nxt['M']=='R':
        res.add(ring[(ring.index('R')+2)%4])
opts={'A':'S','B':'M','C':'O','D':'T'}
assert res=={'S'}
assert sum(v in res for v in opts.values())==1

from fractions import Fraction as F
opts={'A':'-/++','B':'/+-+','C':'+/--','D':'-+/+'}
nums=['8','27','9','6','5']
def ev(ops):
    e=nums[0]+''.join(o+n for o,n in zip(ops,nums[1:]))
    return eval(e.replace('/','*F(1)/'),{'F':F})
good=[k for k,v in opts.items() if ev(v)==0]
assert good==['C']

