import itertools
s=[('toys are gadgets','dj sq ty'),('gadgets are machines','mp ty dj')]
ws=sorted(set(w for a,_ in s for w in a.split())); cs=sorted(set(c for _,b in s for c in b.split()))
sols=set()
for perm in itertools.permutations(cs):
    m=dict(zip(ws,perm))
    if all(set(m[w] for w in a.split())==set(b.split()) for a,b in s): sols.add(m['gadgets'])
assert sols=={'ty','dj'}
opts={'A':{'ty','mp'},'B':{'ty','dj'},'C':{'sq'},'D':{'dj'}}
good=[k for k,v in opts.items() if v==sols]
assert good==['B']

pat='_B___AL__L__'
opts={'A':'BLABBALL','B':'BBALLBAA','C':'LBAALLBA','D':'LALBBABA'}
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in pat)
good=[k for k,v in opts.items() if any(fill(v)==(fill(v)[:p]*12)[:12] for p in (2,3,4))]
assert good==['D']
